      <AnimatePresence>
        {sheet && sheet.kind === 'budget' && <BudgetSheet key='bs' app={app} row={sheet.row} used={used} spent={spend} onClose={close} onDone={(m) => { close(); setToast(m); }} />}
        {sheet && sheet.kind === 'bill' && <BillSheet key='ls' app={app} row={sheet.row} onClose={close} onDone={(m) => { close(); setToast(m); }} />}
