          {toast && <motion.div key={toast} initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: 8 }} transition={{ duration: 0.25, ease: EASE }} className='flex items-center gap-2 rounded-xl bg-[#0E1525] px-4 py-3 text-sm font-medium text-white shadow-[0_12px_30px_-10px_rgba(14,21,37,0.5)]'><Check size={16} className='text-[#6EE7B7]' /> {toast}</motion.div>}
        </AnimatePresence>
      </div>
    </Shell>
  );
}

import React, { useEffect, useMemo, useState } from 'react';
import { motion, AnimatePresence, useReducedMotion } from 'motion/react';
import { LayoutDashboard, List, Target, Sparkles, LogOut, ShoppingCart, Utensils, Truck, ShoppingBag, FileText, HeartPulse, Ticket, TrendingUp, Circle, RefreshCw, Lightbulb, Info } from 'lucide-react';
import type { AppHandle } from '@app/kit/primitives';

type R = Record<string, unknown>;
type Icon = typeof Circle;
const CATS: Record<string, { label: string; color: string; Icon: Icon }> = {
  groceries: { label: 'Groceries', color: '#0E9F6E', Icon: ShoppingCart },
  dining: { label: 'Dining', color: '#D97706', Icon: Utensils },
  transport: { label: 'Transport', color: '#7C5CFA', Icon: Truck },
  shopping: { label: 'Shopping', color: '#DB2777', Icon: ShoppingBag },
  bills: { label: 'Bills', color: '#2F6BFF', Icon: FileText },
  health: { label: 'Health', color: '#0891B2', Icon: HeartPulse },
  fun: { label: 'Fun', color: '#EA580C', Icon: Ticket },
  income: { label: 'Income', color: '#047857', Icon: TrendingUp },
  other: { label: 'Other', color: '#64748B', Icon: Circle },
};
const cat = (k: string) => CATS[k] || CATS.other;
const MINUS = '−';
const money = (n: number, d = 2) => (n < 0 ? MINUS : '') + '$' + Math.abs(n).toLocaleString('en-US', { minimumFractionDigits: d, maximumFractionDigits: d });
const ymd = (d: Date) => d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const MONTHS_LONG = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
const EASE = [0.22, 1, 0.36, 1] as const;
const CARD = 'rounded-2xl bg-white shadow-[0_1px_2px_rgba(14,21,37,0.05),0_8px_24px_-12px_rgba(14,21,37,0.12)]';
const MUTED = 'text-[#5E6776]';
const THEME_FIX = 'html,body{--e-flow-stretch:cubic-bezier(.22,1,.36,1)!important;--e-flow-jelly:cubic-bezier(.22,1,.36,1)!important;--e-flow-jelly-hover:cubic-bezier(.22,1,.36,1)!important;--e-flow-pebble:cubic-bezier(.22,1,.36,1)!important;--e-flow-halo:cubic-bezier(.22,1,.36,1)!important;--e-flow-drop:cubic-bezier(.22,1,.36,1)!important;--e-flow-rubber:cubic-bezier(.22,1,.36,1)!important}*{--font-heading:Manrope,system-ui,-apple-system,"Segoe UI",sans-serif!important;--font-display:Manrope,system-ui,-apple-system,"Segoe UI",sans-serif!important}h1,h2,h3,h4{font-family:Manrope,system-ui,-apple-system,"Segoe UI",sans-serif!important}::selection{background:#D6E2FF;color:#0E1525}.rounded-md{border-radius:6px!important}.rounded-lg{border-radius:8px!important}.rounded-xl{border-radius:12px!important}.rounded-2xl{border-radius:16px!important}.rounded-3xl{border-radius:24px!important}';
const TABS = [
  { k: 'dashboard', label: 'Home', route: '/dashboard', Icon: LayoutDashboard },
  { k: 'transactions', label: 'Activity', route: '/transactions', Icon: List },
  { k: 'budgets', label: 'Budgets', route: '/budgets', Icon: Target },
  { k: 'insights', label: 'Insights', route: '/insights', Icon: Sparkles },
];

function Mark({ size = 32 }: { size?: number }) {
  return (
    <span aria-hidden='true' className='flex shrink-0 flex-col justify-center gap-[3px] rounded-[9px] bg-primary px-[8px]' style={{ width: size, height: size }}>
