      <span className='h-[3px] w-3/4 rounded-full bg-white' />
      <span className='h-[3px] w-1/2 rounded-full bg-white' />
    </span>
  );
}

function Avatar({ name, photo, size = 40 }: { name: string; photo?: string; size?: number }) {
  const ini = name.split(' ').map((s) => s[0] || '').slice(0, 2).join('').toUpperCase();
  if (photo) return <img src={photo} alt='' className='shrink-0 rounded-full bg-[#EEF3FF] object-cover' style={{ width: size, height: size }} />;
  return <span className='flex shrink-0 items-center justify-center rounded-full bg-[#EEF3FF] text-sm font-semibold text-[#1F4FD8]' style={{ width: size, height: size }}>{ini}</span>;
