function Shell({ app, active, children }: { app?: AppHandle; active: string; children: React.ReactNode }) {
  const name = String(app?.user.name || 'You');
  const me = (app?.rows('member') || [])[0] as R | undefined;
  const photo = me && me.photo ? String(me.photo) : undefined;
  return (
    <div className='min-h-screen overflow-x-hidden bg-[#F5F7FB] text-[#0E1525] antialiased lg:flex'>
      <style>{THEME_FIX}</style>
      <aside className='sticky top-0 hidden h-screen w-60 shrink-0 flex-col border-r border-[#E4E8F0] bg-white px-4 py-6 lg:flex'>
        <div className='flex items-center gap-2.5 px-2'><Mark /><span className='text-[17px] font-semibold tracking-[-0.01em]'>Ledgerly</span></div>
        <nav aria-label='Main' className='mt-8 flex flex-col gap-1'>
          {TABS.map((t) => {
            const on = active === t.k;
            return (
              <button key={t.k} aria-current={on ? 'page' : undefined} onClick={() => app?.navigate(t.route)} className={'flex h-11 items-center gap-3 rounded-xl px-3 text-[15px] font-medium transition-colors ' + (on ? 'bg-[#EEF3FF] text-[#1F4FD8]' : 'text-[#5E6776] hover:bg-[#F5F7FB] hover:text-[#0E1525]')}>
                <t.Icon size={18} strokeWidth={on ? 2.2 : 1.8} />{t.label}
              </button>
            );
          })}
        </nav>
        <div className='mt-auto flex items-center gap-3 border-t border-[#E4E8F0] px-2 pt-4'>
          <Avatar name={name} photo={photo} size={36} />
          <div className='min-w-0 flex-1'><div className='truncate text-sm font-semibold'>{name}</div><div className={'text-xs ' + MUTED}>Personal</div></div>
          <button aria-label='Sign out' title='Sign out' onClick={() => app?.auth.signOut()} className='flex h-10 w-10 items-center justify-center rounded-xl text-[#5E6776] hover:bg-[#F5F7FB] hover:text-[#0E1525]'><LogOut size={17} /></button>
        </div>
      </aside>
      <main className='min-w-0 flex-1 pb-28 lg:pb-16'>
        <header className='flex items-center justify-between px-4 pt-3 sm:px-6 lg:hidden'>
          <div className='flex items-center gap-2'><Mark size={28} /><span className='text-base font-semibold tracking-[-0.01em]'>Ledgerly</span></div>
          <button aria-label='Sign out' onClick={() => app?.auth.signOut()} className='flex h-11 w-11 items-center justify-center rounded-full text-[#5E6776] active:bg-white'><LogOut size={19} /></button>
        </header>
        <div className='mx-auto w-full max-w-[1120px] px-4 pt-3 sm:px-6 lg:px-10 lg:pt-10'>{children}</div>
      </main>
      <nav aria-label='Main' className='fixed inset-x-0 bottom-0 z-30 border-t border-[#E4E8F0] bg-white/95 pb-[env(safe-area-inset-bottom)] backdrop-blur lg:hidden'>
        <div className='mx-auto grid max-w-md grid-cols-4'>
          {TABS.map((t) => {
            const on = active === t.k;
            return (
              <button key={t.k} aria-current={on ? 'page' : undefined} onClick={() => app?.navigate(t.route)} className={'flex h-16 flex-col items-center justify-center gap-1 text-xs font-medium ' + (on ? 'text-[#1F4FD8]' : 'text-[#5E6776]')}>
                <t.Icon size={22} strokeWidth={on ? 2.2 : 1.8} />{t.label}
              </button>
            );
          })}
        </div>
      </nav>
    </div>
  );
}

function Rise({ i = 0, className = '', children }: { i?: number; className?: string; children: React.ReactNode }) {
  const reduce = useReducedMotion();
  return (
    <motion.div className={'min-w-0 ' + className} initial={reduce ? false : { opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.4, ease: EASE, delay: reduce ? 0 : i * 0.05 }}>
      {children}
    </motion.div>
  );
}

function useStalled(loading: boolean) {
  const [stalled, setStalled] = useState(false);
  useEffect(() => {
    if (!loading) { setStalled(false); return; }
    const id = window.setTimeout(() => setStalled(true), 12000);
    return () => window.clearTimeout(id);
  }, [loading]);
  return stalled;
}

export default function InsightsScreen({ app }: { app?: AppHandle }) {
  const reduce = useReducedMotion();
  const [now, setNow] = useState<Date | null>(null);
  const [bullets, setBullets] = useState<string[]>([]);
  const [state, setState] = useState<'idle' | 'loading' | 'done'>('idle');
  const [fallback, setFallback] = useState(false);
  const [tip, setTip] = useState('');
  useEffect(() => { setNow(new Date()); }, []);

  const txs = (app?.rows('transaction') || []) as R[];
  const budgets = (app?.rows('budget') || []) as R[];
  const loading = !now || (!!app?.loading('transaction') && txs.length === 0);
  const stalled = useStalled(loading);
  const ym = now ? ymd(now).slice(0, 7) : '';
  const monthName = now ? MONTHS_LONG[now.getMonth()] : 'this month';

  const data = useMemo(() => {
    const months: { key: string; label: string; spent: number; income: number }[] = [];
    if (now) {
      let earliest = ym;
      for (const t of txs) { const k = String(t.date).slice(0, 7); if (k && k < earliest) earliest = k; }
      const span = (now.getFullYear() - Number(earliest.slice(0, 4))) * 12 + (now.getMonth() + 1 - Number(earliest.slice(5, 7)));
      const count = Math.max(3, Math.min(6, span + 1));
      for (let i = count - 1; i >= 0; i--) {
        const d = new Date(now.getFullYear(), now.getMonth() - i, 1);
        months.push({ key: d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0'), label: MONTHS[d.getMonth()], spent: 0, income: 0 });
      }
    }
    const spend: Record<string, number> = {};
    let curCount = 0;
    for (const t of txs) {
      const m = months.find((x) => x.key === String(t.date).slice(0, 7));
      const a = Number(t.amount);
      if (!m) continue;
      if (m.key === ym) curCount++;
      if (a < 0) { m.spent -= a; if (m.key === ym) spend[String(t.category)] = (spend[String(t.category)] || 0) - a; } else m.income += a;
    }
    const cur = months[months.length - 1];
    const prev = months[months.length - 2];
    const past = months.slice(0, -1).filter((m) => m.spent > 0);
    const avg = past.length ? past.reduce((s, m) => s + m.spent, 0) / past.length : 0;
    const list = Object.keys(spend).map((k) => { const lim = budgets.find((b) => String(b.category) === k); return { k, v: spend[k], lim: lim ? Number(lim.monthly_limit) : 0 }; }).sort((a, b) => b.v - a.v);
    const over = list.filter((x) => x.lim > 0 && x.v > x.lim);
    return { months, cur, prev, list, over, avg, curCount };
  }, [txs, budgets, now, ym]);

  const maxSpent = Math.max(1, ...data.months.map((m) => m.spent));
  const spent = data.cur ? data.cur.spent : 0;
  const income = data.cur ? data.cur.income : 0;
  const prevSpent = data.prev ? data.prev.spent : 0;
  const prevName = data.prev ? MONTHS_LONG[MONTHS.indexOf(data.prev.label)] : 'last month';

  const localTake = (): string[] => {
    const top = data.list[0];
    const out: string[] = [];
    out.push('You have spent ' + money(spent, 0) + ' so far in ' + monthName + (top ? ', and ' + cat(top.k).label.toLowerCase() + ' is the biggest share at ' + money(top.v, 0) + '.' : '.'));
    out.push(data.over.length ? data.over.map((o) => cat(o.k).label + ' is ' + money(o.v - o.lim, 0) + ' over its ' + money(o.lim, 0) + ' budget').join('; ') + '.' : 'Every category is still inside its budget.');
    out.push(income >= spent ? 'Income is ' + money(income - spent, 0) + ' ahead of spending, which leaves room to move some into savings.' : 'Spending is ' + money(spent - income, 0) + ' above income this month, so ease off the flexible categories.');
    return out;
  };

  const explain = async () => {
    if (!app || state === 'loading') return;
    setState('loading');
    setBullets([]);
    setTip('');
    const summary = {
      month: monthName,
      spent_so_far: Math.round(spent),
      income_so_far: Math.round(income),
      last_month_spent: Math.round(prevSpent),
      categories: data.list.map((x) => ({ category: x.k, spent: Math.round(x.v), budget: x.lim || null })),
    };
    let out: string[] = [];
    let fb = false;
    let tipLine = '';
    try {
      const text = await app.ai.ask('Explain my month. Here is my data as JSON: ' + JSON.stringify(summary), { system: 'You are Ledgerly, a friendly personal finance coach. Summarise the member spending versus their budgets in exactly 3 bullet points, then one last line that starts with Tip: and gives one practical tip. Each bullet starts with a dash and a space, is at most 28 words, uses real dollar figures from the data, and is plain text with no markdown formatting, no headings and no intro.', maxTokens: 380 });
      out = text.split('\n').map((l) => l.replace(/^[\s\-•*\d.)]+/, '').replace(/\*\*/g, '').trim()).filter((l) => l.length > 8);
      const tl = out.find((l) => /^tip:/i.test(l));
      tipLine = tl ? tl.replace(/^tip:\s*/i, '') : '';
      out = out.filter((l) => !/^tip:/i.test(l)).slice(0, 3);
    } catch (e) { out = []; }
    if (out.length < 3) { out = localTake(); fb = true; tipLine = ''; }
    setFallback(fb);
    setTip(tipLine);
    setBullets(out);
    setState('done');
  };

  return (
    <Shell app={app} active='insights'>
      <Rise>
        <div className='mb-6'>
          <h1 className='text-[26px] font-semibold leading-tight tracking-[-0.02em] lg:text-[32px]'>Insights</h1>
          <p className={'mt-1 text-[15px] ' + MUTED}>How {monthName} is going, and how it compares.</p>
        </div>
      </Rise>

      {loading && stalled ? (
        <div className={CARD + ' flex flex-col items-center px-6 py-14 text-center'}>
          <div className='text-lg font-semibold'>We could not load your numbers</div>
          <p className={'mt-1 max-w-sm text-sm ' + MUTED}>Check your connection, then try again.</p>
          <button onClick={() => app?.navigate('/insights')} className='mt-5 flex h-11 items-center gap-2 rounded-xl bg-primary px-5 text-sm font-semibold text-primary-foreground'><RefreshCw size={16} /> Try again</button>
        </div>
      ) : loading ? (
        <div className='grid gap-5 lg:grid-cols-5' aria-busy='true' aria-label='Loading insights'><div className='h-72 animate-pulse rounded-2xl bg-[#E9EDF4] lg:col-span-3' /><div className='h-72 animate-pulse rounded-2xl bg-[#E9EDF4] lg:col-span-2' /></div>
      ) : (
        <div className='grid grid-cols-[minmax(0,1fr)] gap-5 lg:grid-cols-5 lg:gap-6'>
          <Rise i={1} className='lg:col-span-3'>
            <section className={CARD + ' p-6 lg:p-8'} aria-label='Explain my month' aria-busy={state === 'loading'}>
              <div className='flex items-start gap-4'>
                <span className='flex h-11 w-11 shrink-0 items-center justify-center rounded-xl bg-[#EEF3FF] text-[#1F4FD8]'><Sparkles size={21} /></span>
                <div className='min-w-0'>
                  <h2 className='text-xl font-semibold tracking-[-0.01em]'>Explain my {monthName}</h2>
                  <p className={'mt-1 text-[15px] leading-relaxed ' + MUTED}>Ledgerly reads this month against your budgets and {prevName}, then sums it up in three points.</p>
                </div>
              </div>

              <div className='mt-6' aria-live='polite'>
                {state === 'idle' && (
                  <div className='rounded-xl bg-[#F5F7FB] px-4 py-4 text-sm text-[#3B4453]'>
                    Ready to read <span className='font-semibold tabular-nums'>{data.curCount}</span> transactions and <span className='font-semibold tabular-nums'>{budgets.length}</span> budgets from {monthName}. Only these totals are sent to the assistant.
                  </div>
                )}
                {state === 'loading' && (
                  <div className='space-y-4' aria-label='Writing your summary'>
                    {[0, 1, 2].map((i) => (
                      <div key={i} className='flex gap-3'>
