                      </div>
                    ))}
                  </div>
                )}
                {state === 'done' && (
                  <div>
                    {fallback && (
                      <div className='mb-4 flex gap-2.5 rounded-xl bg-[#FFFBEB] px-4 py-3 text-sm text-[#92400E]'><Info size={17} className='mt-0.5 shrink-0' /><span>The AI assistant is not available right now, so this summary comes straight from your numbers. Try again in a few minutes.</span></div>
                    )}
                    <ol className='space-y-4'>
                      <AnimatePresence>
                        {bullets.map((b, i) => (
                          <motion.li key={b} initial={reduce ? false : { opacity: 0, y: 6 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: reduce ? 0 : i * 0.12, duration: 0.4, ease: EASE }} className='flex gap-3'>
                            <span className='flex h-7 w-7 shrink-0 items-center justify-center rounded-full bg-[#EEF3FF] text-[13px] font-semibold tabular-nums text-[#1F4FD8]'>{i + 1}</span>
                            <span className='pt-0.5 text-[15px] leading-relaxed text-[#1E2636]'>{b}</span>
                          </motion.li>
                        ))}
                      </AnimatePresence>
                    </ol>
                    {tip && (
                      <motion.div initial={reduce ? false : { opacity: 0, y: 6 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: reduce ? 0 : 0.4, duration: 0.4, ease: EASE }} className='mt-5 flex gap-3 rounded-xl bg-[#EEF3FF] px-4 py-3.5'>
                        <Lightbulb size={18} className='mt-0.5 shrink-0 text-[#1F4FD8]' />
                        <p className='text-[15px] leading-relaxed text-[#1E2636]'><span className='font-semibold'>Tip: </span>{tip}</p>
                      </motion.div>
                    )}
                  </div>
