              </div>

              <div className='mt-6 flex flex-wrap items-center gap-x-4 gap-y-3'>
                <button onClick={explain} disabled={state === 'loading' || !app} className={'flex h-11 items-center gap-2 rounded-xl px-5 text-sm font-semibold transition-opacity disabled:opacity-70 ' + (state === 'done' ? 'bg-white text-[#0E1525] ring-1 ring-inset ring-[#DCE2EC] hover:ring-[#B9C2D0]' : 'bg-primary text-primary-foreground hover:opacity-95')}>
                  {state === 'loading' ? <motion.span animate={reduce ? undefined : { rotate: 360 }} transition={{ duration: 1, repeat: Infinity, ease: 'linear' }} className='flex'><RefreshCw size={16} /></motion.span> : state === 'done' ? <RefreshCw size={16} /> : <Sparkles size={16} />}
                  {state === 'loading' ? 'Reading your month…' : state === 'done' ? 'Explain again' : 'Explain my ' + monthName}
                </button>
                {state === 'done' && !fallback && <span className={'text-[13px] ' + MUTED}>Written by AI from your totals. Check figures against Activity.</span>}
              </div>
            </section>
          </Rise>

          <Rise i={2} className='lg:col-span-2'>
            <div className='grid h-full grid-cols-2 gap-4 lg:grid-cols-1 lg:gap-6'>
              <div className={CARD + ' p-5 lg:p-6'}>
                <div className={'text-[13px] font-medium ' + MUTED}>Spent in {monthName}</div>
                <div className='mt-1 text-[28px] font-semibold leading-tight tracking-[-0.02em] tabular-nums lg:text-[34px]'>{money(spent, 0)}</div>
                <div className={'mt-1 text-[13px] font-medium ' + (prevSpent ? (spent > prevSpent ? 'text-[#B91C1C]' : 'text-[#047857]') : MUTED)}>{prevSpent ? (spent > prevSpent ? money(spent - prevSpent, 0) + ' more than ' : money(prevSpent - spent, 0) + ' less than ') + prevName : 'First month tracked'}</div>
              </div>
              <div className={CARD + ' p-5 lg:p-6'}>
                <div className={'text-[13px] font-medium ' + MUTED}>Income in {monthName}</div>
                <div className='mt-1 text-[28px] font-semibold leading-tight tracking-[-0.02em] tabular-nums text-[#047857] lg:text-[34px]'>{money(income, 0)}</div>
                <div className={'mt-1 text-[13px] font-medium ' + (data.over.length ? 'text-[#B91C1C]' : MUTED)}>{data.over.length ? data.over.length + (data.over.length === 1 ? ' budget over its limit' : ' budgets over their limits') : 'Every budget on track'}</div>
              </div>
            </div>
          </Rise>

          <Rise i={3} className='lg:col-span-3'>
            <section className={CARD + ' p-6 lg:p-8'} aria-label='Spending trend'>
              <div className='mb-6 flex flex-wrap items-baseline justify-between gap-2'>
                <h2 className='text-[17px] font-semibold'>Spending by month</h2>
                {data.avg > 0 && <span className={'text-sm ' + MUTED}>Average <span className='font-semibold text-[#0E1525] tabular-nums'>{money(data.avg, 0)}</span> a month</span>}
              </div>
              <div className='flex h-52 items-end gap-3 sm:gap-5' role='img' aria-label={'Monthly spending: ' + data.months.map((m) => m.label + ' ' + money(m.spent, 0)).join(', ')}>
                {data.months.map((m, i) => {
                  const cur = i === data.months.length - 1;
                  return (
                    <div key={m.key} className='flex h-full min-w-0 flex-1 flex-col items-center justify-end gap-2'>
                      <div className={'text-xs font-semibold tabular-nums ' + (cur ? 'text-[#0E1525]' : MUTED)}>{m.spent ? '$' + (m.spent / 1000).toFixed(1).replace('.0', '') + 'k' : ''}</div>
                      <motion.div className='w-full max-w-[48px] rounded-lg' style={{ background: cur ? 'hsl(var(--primary))' : '#C9D6F5', originY: 1 }} initial={reduce ? false : { height: 0 }} animate={{ height: Math.max((m.spent / maxSpent) * 100, 2) + '%' }} transition={{ duration: 0.8, delay: reduce ? 0 : 0.15 + i * 0.06, ease: EASE }} />
                      <div className={'text-[13px] font-medium ' + (cur ? 'text-[#1F4FD8]' : MUTED)}>{m.label}</div>
                    </div>
                  );
                })}
              </div>
              <p className={'mt-4 text-[13px] ' + MUTED}>{monthName} is month to date.</p>
            </section>
          </Rise>

          <Rise i={4} className='lg:col-span-2'>
            <section className={CARD + ' h-full p-6'} aria-label='Where it went'>
              <h2 className='mb-5 text-[17px] font-semibold'>Where it went</h2>
              {data.list.length === 0 ? (
                <p className={'py-6 text-center text-sm ' + MUTED}>No spending recorded in {monthName} yet.</p>
              ) : (
                <ul className='space-y-4'>
                  {data.list.slice(0, 6).map((s, i) => {
                    const c = cat(s.k);
                    const over = s.lim > 0 && s.v > s.lim;
                    return (
                      <li key={s.k}>
                        <div className='mb-1.5 flex items-center justify-between gap-2 text-sm'>
                          <span className='flex items-center gap-2 font-medium'><c.Icon size={15} style={{ color: c.color }} />{c.label}</span>
                          <span className='tabular-nums'><span className={'font-semibold ' + (over ? 'text-[#B91C1C]' : '')}>{money(s.v, 0)}</span>{s.lim > 0 && <span className={MUTED}> / {money(s.lim, 0)}</span>}</span>
                        </div>
                        <div className='h-2 overflow-hidden rounded-full bg-[#EDF0F5]'><motion.div className='h-full rounded-full' style={{ background: over ? '#DC2626' : c.color }} initial={reduce ? false : { width: 0 }} animate={{ width: (data.list[0] ? (s.v / data.list[0].v) * 100 : 0) + '%' }} transition={{ duration: 0.7, delay: reduce ? 0 : 0.2 + i * 0.05, ease: EASE }} /></div>
                      </li>
                    );
                  })}
                </ul>
              )}
            </section>
          </Rise>
        </div>
      )}
    </Shell>
  );
}

