export default function LedgerlyAuth({ app }: { app?: AppHandle }) {
  const auth = app?.auth;
  const reduce = useReducedMotion();
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [name, setName] = useState('');
  const [err, setErr] = useState('');
  const [busy, setBusy] = useState(false);
  const signup = auth?.mode === 'signup';
  const providers = auth?.providers || [];

  const go = async () => {
    if (!auth || busy) return;
    if (!email.trim() || !password) { setErr('Enter your email and password to continue.'); return; }
    setErr('');
    setBusy(true);
    try {
      if (signup) await auth.signUp({ name: name.trim() || email.split('@')[0], email: email.trim(), password });
      else await auth.signIn(email.trim(), password);
    } catch (e) {
      setErr(e instanceof Error ? e.message : 'That did not work. Check your details and try again.');
    }
    setBusy(false);
  };
  const social = async (pname: string) => {
    if (!auth) return;
    setErr('');
    try { await auth.startProvider(pname); } catch (e) { setErr(e instanceof Error ? e.message : 'Could not start that sign-in. Try again.'); }
  };
  const input = 'h-12 w-full rounded-xl border border-[#DCE2EC] bg-white px-4 text-[15px] text-[#0E1525] outline-none transition placeholder:text-[#6A7383] focus:border-primary focus:ring-4 focus:ring-primary/15';
  const lbl = 'mb-1.5 block text-[13px] font-semibold text-[#3B4453]';

  return (
    <div className='min-h-[100dvh] overflow-x-hidden bg-[#F5F7FB] text-[#0E1525] antialiased'>
      <style>{THEME_FIX}</style>
      <div className='mx-auto grid min-h-[100dvh] w-full max-w-[1080px] items-center gap-10 px-4 py-8 sm:px-6 lg:grid-cols-[minmax(0,1fr)_440px] lg:gap-20 lg:px-10'>
        <div className='flex flex-col'>
          <div className='flex items-center gap-2.5'><Mark /><span className='text-[19px] font-semibold tracking-[-0.01em]'>Ledgerly</span></div>
          <h1 className='mt-8 max-w-[480px] text-[30px] font-semibold leading-[1.1] tracking-[-0.025em] sm:text-[40px] lg:mt-12 lg:text-[48px]'>Every account, one clear balance.</h1>
          <p className='mt-4 max-w-[440px] text-base leading-relaxed text-[#5E6776] lg:text-[17px]'>Track checking, savings and cards together, stay inside your budgets, and get each month explained in plain English.</p>
          <div className='mt-12 hidden lg:block'><Preview reduce={reduce} /></div>
        </div>

        <motion.div initial={reduce ? false : { opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.5, ease: EASE }} className='w-full rounded-2xl bg-white p-6 shadow-[0_1px_2px_rgba(14,21,37,0.05),0_20px_50px_-24px_rgba(14,21,37,0.25)] sm:p-8'>
          <h2 className='text-[22px] font-semibold tracking-[-0.02em]'>{signup ? 'Create your account' : 'Sign in'}</h2>
          <p className='mt-1 text-[15px] text-[#5E6776]'>{signup ? 'Free, and set up in under a minute.' : 'Welcome back. Pick up where you left off.'}</p>

          {providers.length > 0 && (
            <div className='mt-6 space-y-2.5'>
              {providers.map((p) => (
                <button key={p.name} type='button' onClick={() => social(p.name)} className='flex h-12 w-full items-center justify-center gap-3 rounded-xl border border-[#DCE2EC] bg-white text-[15px] font-semibold text-[#0E1525] transition-colors hover:border-[#B9C2D0] hover:bg-[#FAFBFD]'>
                  {p.name === 'google' && <GoogleMark />}
                  Continue with {p.label}
                </button>
              ))}
              <div className='flex items-center gap-3 pt-3 text-[13px] font-medium text-[#5E6776]'><span className='h-px flex-1 bg-[#E4E8F0]' />or use your email<span className='h-px flex-1 bg-[#E4E8F0]' /></div>
            </div>
          )}

          <form onSubmit={(e) => { e.preventDefault(); go(); }} className={providers.length > 0 ? 'mt-4' : 'mt-6'}>
            <div className='space-y-4'>
              <AnimatePresence initial={false}>
                {signup && (
                  <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }} exit={{ height: 0, opacity: 0 }} transition={{ duration: 0.25, ease: EASE }} className='overflow-hidden'>
                    <label className={lbl} htmlFor='lg-name'>Name</label>
                    <input id='lg-name' autoComplete='name' className={input} value={name} onChange={(e) => setName(e.target.value)} placeholder='Maya Chen' />
                  </motion.div>
                )}
              </AnimatePresence>
              <div>
                <label className={lbl} htmlFor='lg-email'>Email</label>
                <input id='lg-email' type='email' autoComplete='email' required className={input} value={email} onChange={(e) => setEmail(e.target.value)} placeholder='you@example.com' />
              </div>
              <div>
                <label className={lbl} htmlFor='lg-pass'>Password</label>
                <input id='lg-pass' type='password' autoComplete={signup ? 'new-password' : 'current-password'} required minLength={signup ? 8 : undefined} className={input} value={password} onChange={(e) => setPassword(e.target.value)} placeholder={signup ? 'At least 8 characters' : 'Your password'} />
              </div>
            </div>

            <AnimatePresence>
              {err && <motion.div role='alert' initial={{ opacity: 0, y: -4 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0 }} transition={{ duration: 0.2 }} className='mt-4 rounded-xl bg-[#FEF2F2] px-4 py-3 text-sm font-medium text-[#B91C1C]'>{err}</motion.div>}
            </AnimatePresence>

            <button type='submit' disabled={busy} className='mt-5 flex h-12 w-full items-center justify-center gap-2 rounded-xl bg-primary text-[15px] font-semibold text-primary-foreground transition-opacity hover:opacity-95 disabled:opacity-60'>
              {busy ? 'One moment…' : signup ? 'Create account' : 'Sign in'}{!busy && <ArrowRight size={17} />}
