          </form>

          {auth?.canSignUp !== false && (
            <p className='mt-4 text-center text-sm text-[#5E6776]'>
              {signup ? 'Already have an account? ' : 'New to Ledgerly? '}
              <button type='button' className='inline-flex h-10 items-center font-semibold text-[#1F4FD8] underline-offset-4 hover:underline' onClick={() => { setErr(''); auth?.setMode(signup ? 'login' : 'signup'); }}>{signup ? 'Sign in' : 'Create an account'}</button>
            </p>
          )}

          {!signup && (
            <div className='mt-4 border-t border-[#EDF0F5] pt-5'>
              <div className='text-sm font-semibold text-[#3B4453]'>Try a demo account</div>
              <p className='mt-0.5 text-[13px] text-[#5E6776]'>Tap one to fill in the details, then sign in.</p>
              <div className='mt-3 grid gap-2 sm:grid-cols-2'>
                {DEMOS.map((d) => {
                  const on = email === d.email;
                  return (
                    <button key={d.email} type='button' aria-pressed={on} onClick={() => { setEmail(d.email); setPassword(d.password); setErr(''); }} className={'flex min-h-[56px] items-center gap-3 rounded-xl px-3 py-2 text-left transition-colors ' + (on ? 'bg-[#EEF3FF] ring-2 ring-inset ring-primary' : 'bg-white ring-1 ring-inset ring-[#DCE2EC] hover:ring-[#B9C2D0]')}>
                      <span className='flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-[#EEF3FF] text-[13px] font-semibold text-[#1F4FD8]'>{d.name.split(' ').map((s) => s[0]).join('')}</span>
                      <span className='min-w-0 flex-1'><span className='block text-sm font-semibold text-[#0E1525]'>{d.name}</span><span className='block truncate text-xs text-[#465061]'>{d.email}</span></span>
                      {on && <Check size={16} className='shrink-0 text-[#1F4FD8]' />}
                    </button>
                  );
                })}
              </div>
            </div>
          )}
        </motion.div>
      </div>
    </div>
  );
}

