const ym = String(y) + '-' + String(m + 1).padStart(2, '0');
const date = ym + '-' + String(d).padStart(2, '0');
const bills = await ctx.db.list('bill');
const txs = await ctx.db.list('transaction');
let n = 0;
for (const b of bills) {
  if (b.active === false) continue;
  const day = Number(b.day_of_month);
  const due = day === d || (d === last && day > last);
  if (!due) continue;
  const exists = txs.some((t) => String(t.bill_id) === String(b.id) && String(t.date).slice(0, 7) === ym);
  if (exists) continue;
  await ctx.db.create('transaction', { member_id: b.member_id, bill_id: b.id, title: String(b.name), amount: -Math.abs(Number(b.amount)), category: String(b.category), date: date, note: 'Recurring bill' });
  n++;
}
ctx.log('Created ' + String(n) + ' bill transactions for ' + date);

